        setValue(L.DESC_COMMAND_TEXT_PARAM, "The text to count");
        setValue(L.DESC_COMMAND_SCOPE_PARAM, "global (the variables of the book) or part (the variables on a part)");
        setValue(L.DESC_COMMAND_PART_A_PARAM, "Position of the first part, the first part of the story is 1");
        setValue(L.DESC_COMMAND_PART_B_PARAM, "Position of the second part; 0 compares the first part with the text the model produced first");
        setValue(L.DESC_COMMAND_BRANCH_A_PARAM, "Branch number of the first part; the active branch when omitted");
        setValue(L.DESC_COMMAND_BRANCH_B_PARAM, "Branch number of the second part; the branch of the first part when omitted");
        setValue(L.DESC_COMMAND_GET_BOOK_INFO, "Shows the name, settings, model, totals and tags of the open book.");
        setValue(L.DESC_COMMAND_GET_BOOK_INFO_LLM, "The overview of the book: name, description, language, point of view, tense, style, the model and protocol, how many parts, words and tokens the active branch and the whole book have, the tags and the backup strategy. Reads only. Call it first to learn what the book is.");
        setValue(L.DESC_COMMAND_GET_BOOK_INFO_RETURN, "JSON with the settings and the totals of the book");
        setValue(L.DESC_COMMAND_LIST_PARTS, "Lists the parts of a branch with their position, size, swipes and a preview.");
        setValue(L.DESC_COMMAND_LIST_PARTS_LLM, "Lists the parts of a branch, from the first part of the story: position, number of swipes (alternatives), words, tokens, whether the author edited it, the state of its summary (none, valid, outdated) and a short preview. Paged: offset and limit. A part is given by its handle (the \"handle\" of the lists; it does not change when parts are added or deleted, so prefer it) or by its position on a branch (the first part of the story is 1); the branch is the active one unless the handle of a part of it or a branch number from list-branches is given. Reads only. Options are positional and optional, in the order listed. Every row also has its \"handle\": it does not change when things are added or deleted, and it is what the commands that change the book take.");
        setValue(L.DESC_COMMAND_LIST_PARTS_RETURN, "JSON with the parts of the page: position, swipes, words, tokens, edited, summary state, preview");
        setValue(L.DESC_COMMAND_GET_PART, "Reads the text of a part, or one of its other fields, in slices.");
        setValue(L.DESC_COMMAND_GET_PART_LLM, "Reads a part: a slice of its text (offset, length; the answer says the total length and whether more follows) and the data it was made from (instructions, scene, point of view, present characters), its size, whether it was edited and the model used. The field option reads instead: instructions, scene, pov, present or reasoning. A part is given by its handle (the \"handle\" of the lists; it does not change when parts are added or deleted, so prefer it) or by its position on a branch (the first part of the story is 1); the branch is the active one unless the handle of a part of it or a branch number from list-branches is given. Reads only. Options are positional and optional, in the order listed.");
        setValue(L.DESC_COMMAND_GET_PART_RETURN, "JSON with a slice of the text, its offset and the total length, and the data of the part");
        setValue(L.DESC_COMMAND_LIST_SWIPES, "Lists the alternatives (swipes) of a part.");
        setValue(L.DESC_COMMAND_LIST_SWIPES_LLM, "Lists the swipes of a part: the alternatives generated for the same place of the story. Each has its number, whether it is the one shown, words, whether it was edited, a preview and the branch number that shows it, to read it with get-part. A part is given by its handle (the \"handle\" of the lists; it does not change when parts are added or deleted, so prefer it) or by its position on a branch (the first part of the story is 1); the branch is the active one unless the handle of a part of it or a branch number from list-branches is given. Reads only. Options are positional and optional, in the order listed. Every row also has its \"handle\": it does not change when things are added or deleted, and it is what the commands that change the book take.");
        setValue(L.DESC_COMMAND_LIST_SWIPES_RETURN, "JSON with the swipes: number, shown, words, edited, preview, branch");
        setValue(L.DESC_COMMAND_LIST_BRANCHES, "Lists the branches of the book with their numbers.");
        setValue(L.DESC_COMMAND_LIST_BRANCHES_LLM, "Lists the branches of the story, a branch being a way from the first part to one of the ends. Each has its number (to pass as the branch of other commands; the numbers follow the creation of the ends and change when a branch is added or deleted), whether it is the active one, parts, words, the position after which it parts from the others and a preview of its end. Paged: offset and limit. Reads only. Options are positional and optional, in the order listed. Every row also has its \"handle\": it does not change when things are added or deleted, and it is what the commands that change the book take.");
        setValue(L.DESC_COMMAND_LIST_BRANCHES_RETURN, "JSON with the branches: number, active, parts, words, forkPosition, created, endPreview");
        setValue(L.DESC_COMMAND_GET_PART_METRICS, "Shows the tokens, timings, model and protocol of a part.");
        setValue(L.DESC_COMMAND_GET_PART_METRICS_LLM, "The numbers of a generated part: its tokens and words, prompt and reasoning tokens, the model and protocol that wrote it, the time to the first token and the time of reasoning. A part is given by its handle (the \"handle\" of the lists; it does not change when parts are added or deleted, so prefer it) or by its position on a branch (the first part of the story is 1); the branch is the active one unless the handle of a part of it or a branch number from list-branches is given. Reads only. Options are positional and optional, in the order listed.");
        setValue(L.DESC_COMMAND_GET_PART_METRICS_RETURN, "JSON with the metrics of the part");
        setValue(L.DESC_COMMAND_SHOW_PROMPT, "Shows the prompt a generated part was made from.");
        setValue(L.DESC_COMMAND_SHOW_PROMPT_LLM, "The prompt as it was sent when the part was generated, stored with it: a slice of its text (offset, length), the tokens it had, the breakdown of the tokens by section and the background lore that was added. Parts that were not generated, or were generated before the prompt was stored, have none. A part is given by its handle (the \"handle\" of the lists; it does not change when parts are added or deleted, so prefer it) or by its position on a branch (the first part of the story is 1); the branch is the active one unless the handle of a part of it or a branch number from list-branches is given. Reads only. Options are positional and optional, in the order listed.");
        setValue(L.DESC_COMMAND_SHOW_PROMPT_RETURN, "JSON with a slice of the prompt, its tokens and the token breakdown");
        setValue(L.DESC_COMMAND_SEARCH_PARTS, "Searches the parts of all branches for words.");
        setValue(L.DESC_COMMAND_SEARCH_PARTS_LLM, "Full-text search over the parts of all branches: every word of the query must be in the part (a phrase in double quotes, * matches any characters). Each hit has the position of the part, the branch number when it is not on the active branch, and a snippet around the match. Reads only. Options are positional and optional, in the order listed. Every row also has its \"handle\": it does not change when things are added or deleted, and it is what the commands that change the book take.");
        setValue(L.DESC_COMMAND_SEARCH_PARTS_RETURN, "JSON with the hits: position, branch and snippet");
        setValue(L.DESC_COMMAND_FIND_OCCURRENCES, "Counts where names or words occur in the story.");
        setValue(L.DESC_COMMAND_FIND_OCCURRENCES_LLM, "Continuity check done in code, not in tokens: for each term (a name and its variants) how many parts and occurrences it has and the first parts with a snippet. Searches the active branch unless allBranches is true, and the summaries too when summaries is true. Options in this order: regex (false), caseSensitive (false), summaries (false), allBranches (false), limit (the most parts listed per term, 50). Reads only. Every row also has its \"handle\": it does not change when things are added or deleted, and it is what the commands that change the book take.");
        setValue(L.DESC_COMMAND_FIND_OCCURRENCES_RETURN, "JSON per term: the parts and occurrences found and where");
        setValue(L.DESC_COMMAND_COMPARE_PARTS, "Shows the sentences that differ between two parts.");
        setValue(L.DESC_COMMAND_COMPARE_PARTS_LLM, "Compares two parts sentence by sentence and lists the sentences only one of them has (- from the first, + from the second), up to 200. To compare two swipes give their positions (the same) and their branch numbers from list-swipes. As the second position, 0 compares the first part with the text the model produced first, to see what the author edited. Positions are on a branch (the active one unless a branch number is given). Reads only. Options are positional and optional, in the order listed.");
        setValue(L.DESC_COMMAND_COMPARE_PARTS_RETURN, "JSON with the counts and the sentences that differ");
        setValue(L.DESC_COMMAND_COUNT_TOKENS, "Counts the tokens and words of a text or of a part.");
        setValue(L.DESC_COMMAND_COUNT_TOKENS_LLM, "Counts the tokens of a text, or of the text of a part when the text is the handle of the part (or a part given by position and branch), with the tokenizer of the model of the book (a generic one when it has none), and its words and characters. Use it to plan how much text fits. Reads only.");
        setValue(L.DESC_COMMAND_COUNT_TOKENS_RETURN, "JSON with the tokens, words and characters");
        setValue(L.DESC_COMMAND_LIST_SUMMARIES, "Lists the summaries of a branch and whether they are valid.");
        setValue(L.DESC_COMMAND_LIST_SUMMARIES_LLM, "Lists the summaries generation uses on a branch, from the first: the position of the part that has it, the parts it covers, regular or meta summary, tokens, whether it still describes the story (valid) and how many summaries a meta summary replaces, then how many parts at the end have no summary. Reads only. Options are positional and optional, in the order listed. Every row also has its \"handle\": it does not change when things are added or deleted, and it is what the commands that change the book take.");
        setValue(L.DESC_COMMAND_LIST_SUMMARIES_RETURN, "JSON with the summaries: position, covers, type, tokens, valid");
        setValue(L.DESC_COMMAND_GET_SUMMARY, "Reads the summary of a part.");
        setValue(L.DESC_COMMAND_GET_SUMMARY_LLM, "The summary stored on a part: its text, tokens, type and whether it still describes the story. A summary is stored on the last part of the parts it covers, so most parts have none (hasSummary false). A part is given by its handle (the \"handle\" of the lists; it does not change when parts are added or deleted, so prefer it) or by its position on a branch (the first part of the story is 1); the branch is the active one unless the handle of a part of it or a branch number from list-branches is given. Reads only. Options are positional and optional, in the order listed.");
        setValue(L.DESC_COMMAND_GET_SUMMARY_RETURN, "JSON with the summary of the part");
        setValue(L.DESC_COMMAND_CHECK_SUMMARIES, "Finds the summaries that no longer match the story.");
        setValue(L.DESC_COMMAND_CHECK_SUMMARIES_LLM, "Finds the outdated summaries of a branch (generation drops them): where they are, which parts they cover and which of those parts were edited, which is what made them outdated. Reads only. Options are positional and optional, in the order listed. Every row also has its \"handle\": it does not change when things are added or deleted, and it is what the commands that change the book take.");
        setValue(L.DESC_COMMAND_CHECK_SUMMARIES_RETURN, "JSON with the number of summaries and the outdated ones with the edited parts");
        setValue(L.DESC_COMMAND_GET_TEMPLATE_VARIABLES, "Shows the template variables of the book or of a part.");
        setValue(L.DESC_COMMAND_GET_TEMPLATE_VARIABLES_LLM, "The variables prompt templates set with setvar: the global ones of the book (scope global), or the ones on a part, which follow its branch (scope part; the last part of the branch when no position is given). A part is given by its handle (the \"handle\" of the lists; it does not change when parts are added or deleted, so prefer it) or by its position on a branch (the first part of the story is 1); the branch is the active one unless the handle of a part of it or a branch number from list-branches is given. Reads only. Options are positional and optional, in the order listed.");
        setValue(L.DESC_COMMAND_GET_TEMPLATE_VARIABLES_RETURN, "JSON with the variables and their values");
        setValue(L.DESC_COMMAND_LOREBOOK_PARAM, "The lorebook: its handle or its number from list-lorebooks; the root lorebook (1) when omitted");
        setValue(L.DESC_COMMAND_LORE_ENTRY_PARAM, "The entry: its handle, or its number in its lorebook, the first entry is 1");
        setValue(L.DESC_COMMAND_LORE_FILTER_PARAM, "Only the entries whose name or tag contains this text (case does not matter)");
        setValue(L.DESC_COMMAND_LORE_QUERY_PARAM, "The text to look for in the name, text and comment of the entries (case does not matter)");
        setValue(L.DESC_COMMAND_LIST_LOREBOOKS, "Lists the lorebooks of the open book with their entries and subbooks.");
        setValue(L.DESC_COMMAND_LIST_LOREBOOKS_LLM, "Lists the lorebooks of the book: the root lorebook and the tree of its subbooks, each with its number (the root is 1), name, whether it is enabled, how many entries it has (and how many are enabled), its tags and the numbers of its subbooks. Other lorebooks of the user are not reachable. Lorebooks and entries are given by their handle (prefer it) or by a number: a lorebook by this number, an entry by its number in the lorebook. Reads only. Every row also has its \"handle\": it does not change when things are added or deleted, and it is what the commands that change the book take.");
        setValue(L.DESC_COMMAND_LIST_LOREBOOKS_RETURN, "JSON with the lorebooks: number, name, enabled, entries, enabledEntries, tags, subbooks");
        setValue(L.DESC_COMMAND_LIST_LORE_ENTRIES, "Lists the entries of a lorebook with their settings and a preview.");
        setValue(L.DESC_COMMAND_LIST_LORE_ENTRIES_LLM, "Lists the entries of a lorebook (the root lorebook unless a lorebook number from list-lorebooks is given): the number of the entry in the lorebook, name, whether it is enabled, its order, insertion mode, filtering mode (KEYWORDS_OR / KEYWORDS_AND keys, TEXT or a REGEX), tags, the length of its text and a short preview. A filter keeps the entries whose name or tag contains it; the numbers stay those of the whole lorebook. Paged: offset and limit. Entries are addressed by their number in the lorebook (the first is 1). Reads only. Options are positional and optional, in the order listed. Every row also has its \"handle\": it does not change when things are added or deleted, and it is what the commands that change the book take.");
        setValue(L.DESC_COMMAND_LIST_LORE_ENTRIES_RETURN, "JSON with the entries of the page: entry, name, enabled, order, insertion, filtering, tags, payloadLength, preview");
        setValue(L.DESC_COMMAND_GET_LORE_ENTRY, "Shows one lorebook entry with its settings and text.");
        setValue(L.DESC_COMMAND_GET_LORE_ENTRY_LLM, "Reads one entry of a lorebook (the root lorebook unless a lorebook number from list-lorebooks is given): name, whether it is enabled, order, insertion mode, filtering mode and its keys (the text or regular expression that activates it), tags and negative tags, the comment and a slice of the text with its offset and total length (offset and length page through a long text). The entry is given by its handle, or by its number in the lorebook (the first is 1, see list-lore-entries). Reads only. Options are positional and optional, in the order listed. Every row also has its \"handle\": it does not change when things are added or deleted, and it is what the commands that change the book take.");
        setValue(L.DESC_COMMAND_GET_LORE_ENTRY_RETURN, "JSON with the entry: name, enabled, order, insertion, filtering, keys, tags, negativeTags, comment and a slice of the payload");
        setValue(L.DESC_COMMAND_SEARCH_LORE, "Searches the names, texts and comments of the lorebook entries.");
        setValue(L.DESC_COMMAND_SEARCH_LORE_LLM, "Finds the entries of all the lorebooks of the book whose name, text or comment contain the query (case does not matter; with regex the query is a regular expression). Each hit gives the lorebook number, the entry number, the name, which of name, text and comment match and a snippet around the first match; found is the number of entries that match, hits is limited. Reads only. Options are positional and optional, in the order listed. Every row also has its \"handle\": it does not change when things are added or deleted, and it is what the commands that change the book take.");
        setValue(L.DESC_COMMAND_SEARCH_LORE_RETURN, "JSON with found and the hits: lorebook, entry, name, matchedIn, snippet");
        setValue(L.DESC_COMMAND_PREVIEW_TEXT_PARAM, "The text the filters of the entries are looked for in, as the user prompt of a turn is");
        setValue(L.DESC_COMMAND_PREVIEW_LORE_ACTIVATION, "Shows which lorebook entries a generation would use for a text or for a part, and why.");
        setValue(L.DESC_COMMAND_PREVIEW_LORE_ACTIVATION_LLM, "Tells which entries of the lorebooks of the book the generation would put into the prompt for a text, or for a turn like the one that made a part (given by position and, optionally, branch number): the filter of an entry is looked for in the text, or, with a part, in the user prompt of the book rendered from the instructions, scene, point of view and present characters stored with the part. Each entry used has its lorebook number, entry number, name and the reason (CONSTANT: no filter; FILTER_MATCHED); the ones not used have the reason too (DISABLED, NEGATIVE_TAG or MISSING_TAG against the tags of the book, FILTER_NOT_MATCHED). Also the lore text that would be inserted, with its tokens, split into the lore block and the lore that goes before the user prompt. The rest of the story is not available to the templates of the entries here. Reads only. Options are positional and optional, in the order listed. Every row also has its \"handle\": it does not change when things are added or deleted, and it is what the commands that change the book take.");
        setValue(L.DESC_COMMAND_PREVIEW_LORE_ACTIVATION_RETURN, "JSON with the entries used and not used (with the reasons) and the lore text with its tokens");
        setValue(L.DESC_AGENT_COMMAND_COMPACT, "Summarizes everything so far and replaces the earlier rounds with the summary, to free the context. The argument, if any, is what the summary should stress.");
        setValue(L.DESC_AGENT_COMMAND_CLEAR_WORKSPACE, "Deletes all the files and folders of the workspace of the agent. The arguments are the files, folders (with what is in them) or patterns such as *.md to keep, separated by spaces (a path with spaces in double quotes); the folders above a kept file stay. If something to keep is not there, nothing is deleted.");
        setValue(L.DESC_COMMAND_OLD_PARAM, "The text to replace, exactly as it is in the part; it has to be found exactly once");
        setValue(L.DESC_COMMAND_NEW_PARAM, "The text to put in its place, may be empty to delete the old one");
        setValue(L.DESC_COMMAND_WRITE_FIELD_PARAM, "The field to change: response (the text of the part, default), instructions, scene, pov or present");
        setValue(L.DESC_COMMAND_NEW_TEXT_PARAM, "The text");
        setValue(L.DESC_COMMAND_SEPARATOR_PARAM, "What goes between the old end and the new text; a blank line when omitted (nothing when the part is empty)");
        setValue(L.DESC_COMMAND_TURN_INSTRUCTIONS_PARAM, "The instructions of the turn the part was made from; empty clears them, omitted leaves them as they are");
        setValue(L.DESC_COMMAND_TURN_SCENE_PARAM, "The scene setting of the turn; empty clears it, omitted leaves it as it is");
        setValue(L.DESC_COMMAND_TURN_POV_PARAM, "The point of view character of the turn; empty clears it, omitted leaves it as it is");
        setValue(L.DESC_COMMAND_TURN_PRESENT_PARAM, "The characters present in the turn; empty clears them, omitted leaves them as they are");
        setValue(L.DESC_COMMAND_EDIT_PART, "Replaces a piece of the text of a part by another text. Parameters: part (handle), old, new, field.");
        setValue(L.DESC_COMMAND_EDIT_PART_LLM, "Changes a part of the story: the piece of text `old` is replaced by `new`. `old` has to match exactly once in the part (the same spaces and line breaks), otherwise nothing is changed and the error says how many times it was found: take more of the text around it. The part is given by its handle. Flags the part as edited, counts its words and tokens, and tells which summaries became outdated (then run revalidate-summaries if they are still right, or regenerate them). With `field` the instructions, scene, pov or present characters of the turn are edited instead of the text. Changes the book.");
        setValue(L.DESC_COMMAND_EDIT_PART_RETURN, "JSON with the part (handle, position, words, tokens, edited) and the summaries that became outdated");
        setValue(L.DESC_COMMAND_REPLACE_PART_TEXT, "Replaces the whole text of a part. Parameters: part (handle), text, field.");
        setValue(L.DESC_COMMAND_REPLACE_PART_TEXT_LLM, "Replaces the whole text of a part of the story by `text` (or the whole instructions, scene, pov or present characters of the turn with `field`). The old text is lost, so for a small change use edit-part, and to add at the end use append-to-part. The part is given by its handle. Flags the part as edited, counts its words and tokens, and tells which summaries became outdated. Changes the book; the user is asked to confirm, an agent is covered by its destructive mode.");
        setValue(L.DESC_COMMAND_REPLACE_PART_TEXT_RETURN, "JSON with the part (handle, position, words, tokens, edited) and the summaries that became outdated");
        setValue(L.DESC_COMMAND_APPEND_TO_PART, "Adds text to the end of a part. Parameters: part (handle), text, separator.");
        setValue(L.DESC_COMMAND_APPEND_TO_PART_LLM, "Adds `text` to the end of the text of a part of the story, after `separator` (a blank line when omitted, nothing when the part is empty). Use it to continue a part; to write a new part use create-part. The part is given by its handle. Flags the part as edited, counts its words and tokens, and tells which summaries became outdated. Changes the book.");
        setValue(L.DESC_COMMAND_APPEND_TO_PART_RETURN, "JSON with the part (handle, position, words, tokens, edited) and the summaries that became outdated");
        setValue(L.DESC_COMMAND_SET_PART_FIELDS, "Changes what a part was made from: instructions, scene, pov and present characters. Parameters: part (handle), instructions, scene, pov, present.");
        setValue(L.DESC_COMMAND_SET_PART_FIELDS_LLM, "Changes the turn input stored with a part of the story: the instructions, the scene setting, the point of view character and the present characters, which a new generation of the part (swipe, regenerate) is made from again. Only the fields that are given are changed, an empty text clears a field. Does not change the text of the part. The part is given by its handle. Changes the book.");
        setValue(L.DESC_COMMAND_SET_PART_FIELDS_RETURN, "JSON with the part and the turn input it has now");
        setValue(L.DESC_COMMAND_PART_HANDLE_PARAM, "The handle of the part (the \"handle\" of the lists, e.g. of list-parts); a position is not accepted");
        setValue(L.DESC_COMMAND_PARENT_PARAM, "The part after which the new part comes (its handle); the last part of the active branch when omitted, the first part of the story when the book is empty");
        setValue(L.DESC_COMMAND_SUMMARY_TEXT_PARAM, "The new text of the summary");
        setValue(L.DESC_COMMAND_UNWIND_PARAM, "For a meta summary bring back the summary it replaced instead of leaving the part without one; false when omitted");
        setValue(L.DESC_COMMAND_REVALIDATE_PART_PARAM, "The part whose summary is revalidated (its handle); all the summaries of the active branch when omitted");
        setValue(L.DESC_COMMAND_BOOK_NAME_PARAM, "The new name of the book");
        setValue(L.DESC_COMMAND_BOOK_DESCRIPTION_PARAM, "The new description of the book");
        setValue(L.DESC_COMMAND_BOOK_POV_PARAM, "The narrative point of view of the book, a free text such as \"Third person limited\"");
        setValue(L.DESC_COMMAND_BOOK_TENSE_PARAM, "The narrative tense of the book, a free text such as \"Past\"");
        setValue(L.DESC_COMMAND_BOOK_STYLE_PARAM, "The style the book is written in, a free text");
        setValue(L.DESC_COMMAND_BOOK_LANGUAGE_PARAM, "The language of the book: its name (English) or ISO 639-1 code (en)");
        setValue(L.DESC_COMMAND_BOOK_TEMPLATE_PARAM, "The master template of the book, the system prompt of every generation (a Handlebars template)");
        setValue(L.DESC_COMMAND_BOOK_USER_PROMPT_PARAM, "The template of the user prompt of a turn");
        setValue(L.DESC_COMMAND_BOOK_SUMMARY_PROMPT_PARAM, "The template of the prompt that makes a summary");
        setValue(L.DESC_COMMAND_BOOK_META_SUMMARY_PROMPT_PARAM, "The template of the prompt that makes a meta summary");
        setValue(L.DESC_COMMAND_TAGS_ADD_PARAM, "Tags to add to the book, separated by commas");
        setValue(L.DESC_COMMAND_TAGS_REMOVE_PARAM, "Tags to take off the book, separated by commas");
        setValue(L.DESC_COMMAND_CREATE_PART, "Writes a new part of the story. Parameters: text, parent (handle), instructions, scene, pov, present.");
        setValue(L.DESC_COMMAND_CREATE_PART_LLM, "Adds a new part with the given text to the story: after the part `parent` (its handle), or after the last part of the active branch when `parent` is left out (the first part of an empty book). A part that continues a part which already has a continuation starts a new branch. The new part becomes the end of the active branch. Optionally stores the turn input (instructions, scene, pov, present) it stands for. Use it to write text yourself; to have the model write it use next. Changes the book. Returns the handle of the new part.");
        setValue(L.DESC_COMMAND_CREATE_PART_RETURN, "JSON with the new part (handle, position, words, tokens) and the length of the branch");
        setValue(L.DESC_COMMAND_BRANCH_PART, "Makes a copy of a part next to it as a new branch. Parameters: part (handle).");
        setValue(L.DESC_COMMAND_BRANCH_PART_LLM, "Copies the part (and its summary) as its sibling, a new swipe that starts a new branch, and makes the copy the end of the active branch. The parts that follow the original stay with the original. Use it to try another version of a part without losing the first one. The part is given by its handle. Changes the book. Returns the handle of the copy.");
        setValue(L.DESC_COMMAND_BRANCH_PART_RETURN, "JSON with the new part (handle, position, words, tokens) and the handle it was copied from");
        setValue(L.DESC_COMMAND_DELETE_PART, "Deletes a part of the story; the parts that follow it stay. Parameters: part (handle).");
        setValue(L.DESC_COMMAND_DELETE_PART_LLM, "Deletes a part of the story and its summary. The parts that followed it stay and continue its parent, so everything after it moves one position up. Summaries of the parts after it may become outdated (the answer lists them). The part is given by its handle. Changes the book; the user is asked to confirm, an agent is covered by its destructive mode.");
        setValue(L.DESC_COMMAND_DELETE_PART_RETURN, "JSON with the handle of the deleted part, how many parts followed it, the active part now and the summaries that became outdated");
        setValue(L.DESC_COMMAND_SWITCH_BRANCH, "Makes the branch through a part the active one. Parameters: part (handle).");
        setValue(L.DESC_COMMAND_SWITCH_BRANCH_LLM, "Makes the branch that goes through the part the active branch of the book: the end of it is the newest continuation below the part. What choosing another swipe does. The part is given by its handle (see list-swipes and list-branches). Changes which parts the commands without a branch work on, and what the next generation continues. Changes the book.");
        setValue(L.DESC_COMMAND_SWITCH_BRANCH_RETURN, "JSON with the part, the handle of the end of the branch and its length");
        setValue(L.DESC_COMMAND_SET_SUMMARY, "Replaces the text of the summary of a part. Parameters: part (handle), text.");
        setValue(L.DESC_COMMAND_SET_SUMMARY_LLM, "Replaces the text of the summary that sits on a part of the story (the part must have one). The summary stands for the parts up to its part; its tokens are counted again. A meta summary above it that includes it may become outdated (the answer lists them). The part is given by its handle. Changes the book.");
        setValue(L.DESC_COMMAND_SET_SUMMARY_RETURN, "JSON with the part, the tokens of the summary and the summaries that became outdated");
        setValue(L.DESC_COMMAND_REMOVE_SUMMARY, "Removes the summary of a part. Parameters: part (handle), unwind.");
        setValue(L.DESC_COMMAND_REMOVE_SUMMARY_LLM, "Removes the summary that sits on a part of the story, so the generation uses the parts themselves again in its place. With `unwind` a meta summary is replaced by the summary it had replaced instead. The part is given by its handle. Changes the book; the user is asked to confirm, an agent is covered by its destructive mode.");
        setValue(L.DESC_COMMAND_REMOVE_SUMMARY_RETURN, "JSON with the part and whether it has a summary now");
        setValue(L.DESC_COMMAND_REVALIDATE_SUMMARIES, "Says the outdated summaries still describe the story. Parameters: part (handle).");
        setValue(L.DESC_COMMAND_REVALIDATE_SUMMARIES_LLM, "Marks the summaries that became outdated by an edit as valid again: the hash of the story they describe is worked out anew. Use it only when you checked that what the summary says is still true after the edit (a typo fixed, a name changed); a summary that describes events that changed has to be made again with regenerate-summary. Without `part` all the summaries of the active branch, with `part` only the summary of that part (its handle). Changes the book.");
        setValue(L.DESC_COMMAND_REVALIDATE_SUMMARIES_RETURN, "JSON with how many summaries were revalidated and their parts");
        setValue(L.DESC_COMMAND_SET_BOOK_INFO, "Changes the name, description, point of view, tense, style or language of the book. Parameters: name, description, pov, tense, style, language.");
        setValue(L.DESC_COMMAND_SET_BOOK_INFO_LLM, "Changes the descriptive settings of the book: its name, description, narrative point of view, tense, style and language. Only the values that are given are changed, the rest stays (an empty text clears a field, the name can't be empty). The language, point of view, tense and style are used in the prompts of the generation. The model, the lorebook and the prompt templates are not changed here. Changes the book.");
        setValue(L.DESC_COMMAND_SET_BOOK_INFO_RETURN, "JSON with the settings of the book after the change");
        setValue(L.DESC_COMMAND_SET_BOOK_PROMPTS, "Replaces the prompt templates of the book. Parameters: template, userPrompt, summaryPrompt, metaSummaryPrompt.");
        setValue(L.DESC_COMMAND_SET_BOOK_PROMPTS_LLM, "Replaces the prompt templates the generation of the book is made with: the master template (the system prompt), the user prompt of a turn, and the prompts of the summary and of the meta summary. Only the templates that are given are changed. Each is checked first: a template that is not valid is refused and nothing is changed, one that uses names that do not exist is saved and the answer says which. Every later generation of the book uses the templates, so a bad one spoils the story: change them only when asked to. Changes the book; the user is asked to confirm, an agent is covered by its destructive mode.");
        setValue(L.DESC_COMMAND_SET_BOOK_PROMPTS_RETURN, "JSON with the templates that were changed and the warnings about names that do not exist");
        setValue(L.DESC_COMMAND_SET_BOOK_TAGS, "Adds tags to the book or takes them off. Parameters: add, remove (comma separated).");
        setValue(L.DESC_COMMAND_SET_BOOK_TAGS_LLM, "Adds tags to the book and takes tags off it; both are lists separated by commas, either can be left out. The tags of the book decide which lorebook entries that are limited to tags are used. A tag that does not exist is made. Changes the book.");
        setValue(L.DESC_COMMAND_SET_BOOK_TAGS_RETURN, "JSON with the tags of the book after the change");
        setValue(L.DESC_COMMAND_LORE_ENTRY_HANDLE_PARAM, "The handle of the entry (the \"handle\" of list-lore-entries); a number is not accepted");
        setValue(L.DESC_COMMAND_LOREBOOK_HANDLE_PARAM, "The handle of the lorebook (the \"handle\" of list-lorebooks); a number is not accepted");
        setValue(L.DESC_COMMAND_TARGET_LOREBOOK_PARAM, "The handle of the lorebook the entry is in; the root lorebook when omitted");
        setValue(L.DESC_COMMAND_LORE_NAME_PARAM, "The name of the entry");
        setValue(L.DESC_COMMAND_LORE_PAYLOAD_PARAM, "The text of the entry, a Handlebars template; it goes into the prompt when the entry is used");
        setValue(L.DESC_COMMAND_LORE_COMMENT_PARAM, "A note about the entry for the author, it is not put into the prompt");
        setValue(L.DESC_COMMAND_LORE_ENABLED_PARAM, "Whether the entry is used, true when omitted");
        setValue(L.DESC_COMMAND_LORE_ORDER_PARAM, "Where the entry comes among the used entries of all the lorebooks: lower comes first, the same order by creation time; 100 when omitted. get-lore-entry and list-lore-entries show the order of the others");
        setValue(L.DESC_COMMAND_LORE_KEYS_PARAM, "The words (a list separated by commas, like \"Name, Lastname\") or the regular expression in the text of the turn that make the entry used; empty for an entry that is always used");
        setValue(L.DESC_COMMAND_LORE_FILTERING_MODE_PARAM, "How the keys are matched: KEYWORDS_OR (keys are a comma separated list, any of them in the text makes the entry used), KEYWORDS_AND (all of them must be in the text), TEXT (the keys are one text) or REGEX; KEYWORDS_OR when omitted on creation, unchanged on update");
        setValue(L.DESC_COMMAND_LORE_INSERTION_MODE_PARAM, "Where the text goes: IN_LORE_BLOCK (in the lore block, in the order of the entries) or BEFORE_USER_PROMPT (right before the request, where the model pays most attention; for what must influence this very part, use sparingly); IN_LORE_BLOCK when omitted");
        setValue(L.DESC_COMMAND_LORE_TAGS_PARAM, "Tags of the entry, separated by commas: the entry is used only in books that have one of them");
        setValue(L.DESC_COMMAND_LORE_TAGS_ADD_PARAM, "Tags to add to the entry, separated by commas");
        setValue(L.DESC_COMMAND_LORE_TAGS_REMOVE_PARAM, "Tags to take off the entry, separated by commas");
        setValue(L.DESC_COMMAND_LORE_NEGATIVE_ADD_PARAM, "Negative tags to add, separated by commas: the entry is not used in books that have one of them");
        setValue(L.DESC_COMMAND_LORE_NEGATIVE_REMOVE_PARAM, "Negative tags to take off the entry, separated by commas");
        setValue(L.DESC_COMMAND_LOREBOOK_NAME_PARAM, "The name of the lorebook");
        setValue(L.DESC_COMMAND_LOREBOOK_ENABLED_PARAM, "Whether the lorebook is used");
        setValue(L.DESC_COMMAND_PARENT_LOREBOOK_PARAM, "The handle of the lorebook that gets the new one as a subbook; the root lorebook when omitted");
        setValue(L.DESC_COMMAND_SUBBOOK_PARAM, "The handle of the lorebook that is (or stops being) a subbook");
        setValue(L.DESC_COMMAND_CREATE_LORE_ENTRY, "Adds an entry to a lorebook. Parameters: name, payload, lorebook (handle), comment, enabled, order, keys, filteringMode, insertionMode, tags.");
        setValue(L.DESC_COMMAND_CREATE_LORE_ENTRY_LLM, "Adds a new entry to a lorebook of the book (the root lorebook when `lorebook` is left out). `payload` is the text that goes into the prompt, a Handlebars template. An entry without `keys` is always used, otherwise it is used when the keys are in the text of the turn: `keys` is a list of words separated by commas (for example \"Anna, Novak\"), the entry is used when any of them is there (filteringMode KEYWORDS_OR, the default) or when all of them are (KEYWORDS_AND); filteringMode TEXT takes the whole `keys` as one text and REGEX as a regular expression. A problem of the template or of the regular expression does not stop the save, it is reported in the answer: fix it with update-lore-entry. `order` (lower comes first, 100 when omitted) puts the entry earlier or later among the used entries: read the `order` of the others with list-lore-entries to place it between them. `insertionMode` BEFORE_USER_PROMPT moves the text from the lore block to right before the request. Changes the book. Returns the handle of the entry.");
        setValue(L.DESC_COMMAND_CREATE_LORE_ENTRY_RETURN, "JSON with the entry (handle, name) and the problems of its text or filter, if any");
        setValue(L.DESC_COMMAND_UPDATE_LORE_ENTRY, "Changes the fields of a lorebook entry. Parameters: entry (handle), name, payload, comment, enabled, order, keys, filteringMode, insertionMode.");
        setValue(L.DESC_COMMAND_UPDATE_LORE_ENTRY_LLM, "Changes the entry with the given handle: only the fields that are given are changed. To change a piece of a long text, read it with get-lore-entry and give the whole new `payload`. A problem of the template or of the regular expression does not stop the save, it is reported in the answer. `order` and `insertionMode` move the entry in the prompt (see create-lore-entry). To change the tags use set-lore-entry-tags, to move it move-lore-entry. Changes the book.");
        setValue(L.DESC_COMMAND_UPDATE_LORE_ENTRY_RETURN, "JSON with the entry (handle, name) and the problems of its text or filter, if any");
        setValue(L.DESC_COMMAND_DELETE_LORE_ENTRY, "Deletes an entry of a lorebook. Parameters: entry (handle).");
        setValue(L.DESC_COMMAND_DELETE_LORE_ENTRY_LLM, "Deletes the entry with the given handle from its lorebook. The numbers of the entries after it in the lorebook change, the handles do not. Changes the book; the user is asked to confirm, an agent is covered by its destructive mode.");
        setValue(L.DESC_COMMAND_DELETE_LORE_ENTRY_RETURN, "JSON with the handle and the name of the deleted entry");
        setValue(L.DESC_COMMAND_MOVE_LORE_ENTRY, "Moves an entry to another lorebook of the book. Parameters: entry (handle), lorebook (handle).");
        setValue(L.DESC_COMMAND_MOVE_LORE_ENTRY_LLM, "Moves the entry to another lorebook of the book (the root lorebook or one of its subbooks). Its fields and tags stay. Changes the book.");
        setValue(L.DESC_COMMAND_MOVE_LORE_ENTRY_RETURN, "JSON with the entry (handle, name) and the problems of its text or filter, if any");
        setValue(L.DESC_COMMAND_SET_LORE_ENTRY_TAGS, "Adds and takes off the tags and the negative tags of an entry. Parameters: entry (handle), add, remove, addNegative, removeNegative (comma separated).");
        setValue(L.DESC_COMMAND_SET_LORE_ENTRY_TAGS_LLM, "Changes the tags of the entry with the given handle; each of the lists is separated by commas and can be left out. An entry with tags is used only in books that have one of them, an entry with negative tags is not used in books that have one of them (see the tags of the book, set-book-tags). A tag that does not exist is made. Changes the book.");
        setValue(L.DESC_COMMAND_SET_LORE_ENTRY_TAGS_RETURN, "JSON with the tags and the negative tags of the entry after the change");
        setValue(L.DESC_COMMAND_CREATE_LOREBOOK, "Makes a new lorebook that is a subbook of another one. Parameters: name, parent (handle).");
        setValue(L.DESC_COMMAND_CREATE_LOREBOOK_LLM, "Makes a new, empty lorebook and adds it as a subbook of the lorebook `parent` (the root lorebook when left out), so its entries are used in the book. Changes the book. Returns the handle of the new lorebook.");
        setValue(L.DESC_COMMAND_CREATE_LOREBOOK_RETURN, "JSON with the new lorebook (handle, number, name)");
        setValue(L.DESC_COMMAND_SET_LOREBOOK, "Renames a lorebook or switches it on or off. Parameters: lorebook (handle), name, enabled.");
        setValue(L.DESC_COMMAND_SET_LOREBOOK_LLM, "Changes the name of a lorebook of the book, or whether it is used: the entries of a disabled lorebook are not used. Only the values that are given are changed. Changes the book.");
        setValue(L.DESC_COMMAND_SET_LOREBOOK_RETURN, "JSON with the lorebook (handle, number, name, enabled)");
        setValue(L.DESC_COMMAND_ADD_SUBBOOK, "Makes a lorebook of the book a subbook of another. Parameters: lorebook (handle), subbook (handle).");
        setValue(L.DESC_COMMAND_ADD_SUBBOOK_LLM, "Makes the lorebook `subbook` a subbook of the lorebook `lorebook`, so its entries are used wherever the lorebook is. Both have to be lorebooks of this book; a lorebook can't contain itself, directly or through its subbooks (that is refused). A lorebook that was deleted or taken out of its parent earlier in this run can be named by its handle as `subbook`: adding it brings it back, with its entries. Changes the book.");
        setValue(L.DESC_COMMAND_ADD_SUBBOOK_RETURN, "JSON with the lorebook and its subbooks");
        setValue(L.DESC_COMMAND_REMOVE_SUBBOOK, "Stops a lorebook being a subbook of another. Parameters: lorebook (handle), subbook (handle).");
        setValue(L.DESC_COMMAND_REMOVE_SUBBOOK_LLM, "Takes the lorebook `subbook` out of the subbooks of the lorebook `lorebook`; nothing happens when it is not one. The lorebook is not deleted, but when no other lorebook has it as a subbook, its entries are not used in the book any more, but you can still name it by its handle and add it again with add-subbook. Changes the book.");
        setValue(L.DESC_COMMAND_REMOVE_SUBBOOK_RETURN, "JSON with the lorebook and its subbooks");
        setValue(L.DESC_COMMAND_DELETE_LOREBOOK, "Deletes a lorebook with its entries. Parameters: lorebook (handle).");
        setValue(L.DESC_COMMAND_DELETE_LOREBOOK_LLM, "Deletes a lorebook of the book with all its entries, and takes it out of the subbooks of the lorebooks that had it. It is only marked as deleted: add-subbook with its handle brings it back with its entries. The root lorebook of the book can't be deleted. Changes the book; the user is asked to confirm, an agent is covered by its destructive mode.");
        setValue(L.DESC_COMMAND_DELETE_LOREBOOK_RETURN, "JSON with the handle and the name of the deleted lorebook and how many entries it had");
        setValue(L.DESC_COMMAND_MAX_HITS_PARAM, "Refuse to replace when there are more matches than this; no limit when omitted");
        setValue(L.DESC_COMMAND_DRY_RUN_PARAM, "Only count the matches and show a few of them, change nothing; false when omitted");
        setValue(L.DESC_COMMAND_GEN_INSTRUCTIONS_PARAM, "What the new part should do or contain; for swipe and regenerate the instructions the part was made from when omitted");
        setValue(L.DESC_COMMAND_GEN_SCENE_PARAM, "The scene setting of the turn; for swipe and regenerate the one the part was made from when omitted");
        setValue(L.DESC_COMMAND_GEN_POV_PARAM, "The point of view character of the turn; for swipe and regenerate the one the part was made from when omitted");
        setValue(L.DESC_COMMAND_GEN_PRESENT_PARAM, "The characters present in the turn; for swipe and regenerate the ones the part was made from when omitted");
        setValue(L.DESC_COMMAND_AFTER_PART_PARAM, "The part to continue after (its handle), which becomes the end of the active branch first; the end of the active branch when omitted");
        setValue(L.DESC_COMMAND_GEN_PROFILE_PARAM, "The role of one of the model profiles of the agent to write with; the main profile when omitted");
        setValue(L.DESC_COMMAND_GEN_PART_PARAM, "The part to write again (its handle); it has to be the last part of its branch. The end of the active branch when omitted");
        setValue(L.DESC_COMMAND_META_FROM_PARAM, "The newest part of the range to merge (its handle); the meta summary sits on it");
        setValue(L.DESC_COMMAND_META_TO_PARAM, "The oldest part of the range to merge (its handle)");
        setValue(L.DESC_COMMAND_NEXT, "Has the model write the next part of the story. Parameters: scene, pov, present, instructions, after (handle), profile.");
        setValue(L.DESC_COMMAND_NEXT_LLM, "Has the model write the next part of the story after the end of the active branch (or after the part `after`), the way the New turn button does: the prompt is built from the book (template, lore, summaries, the story so far) and the turn input given here. Slow and costs tokens of the model of the book (or of the agent's `profile`); only one generation of a book runs at a time, the others wait. The new part becomes the end of the active branch. Returns the handle of the new part; read it with get-part. Changes the book. Asynchronous.");
        setValue(L.DESC_COMMAND_NEXT_RETURN, "JSON with the new part (handle, position, words, tokens, model) and the warnings of the generation");
        setValue(L.DESC_COMMAND_SWIPE, "Has the model write another version of the last part, next to the first one. Parameters: part (handle), scene, pov, present, instructions, profile.");
        setValue(L.DESC_COMMAND_SWIPE_LLM, "Has the model write another version of a part (a swipe): a new sibling of the part made from the same turn (or the changed turn input given here), which becomes the end of the active branch; the first version stays as another branch (see list-swipes, switch-branch). The part has to be the last part of its branch. Slow and costs tokens; only one generation of a book runs at a time. Returns the handle of the new part. Changes the book. Asynchronous.");
        setValue(L.DESC_COMMAND_SWIPE_RETURN, "JSON with the new part (handle, position, words, tokens, model) and the warnings of the generation");
        setValue(L.DESC_COMMAND_REGENERATE, "Has the model write the last part again, replacing its text. Parameters: part (handle), scene, pov, present, instructions, profile.");
        setValue(L.DESC_COMMAND_REGENERATE_LLM, "Has the model write the last part of a branch again and replaces the text of the part in place (to keep the old one use swipe). The part has to be the last part of its branch. The old text is lost, unless the generation fails, then it stays. Slow and costs tokens; only one generation of a book runs at a time. Returns the handle of the part. Changes the book; the user is asked to confirm, an agent is covered by its destructive mode. Asynchronous.");
        setValue(L.DESC_COMMAND_REGENERATE_RETURN, "JSON with the new part (handle, position, words, tokens, model) and the warnings of the generation");
        setValue(L.DESC_COMMAND_REGENERATE_SUMMARY, "Has the model make the summary that ends at a part again. Parameters: part (handle).");
        setValue(L.DESC_COMMAND_REGENERATE_SUMMARY_LLM, "Has the model write the summary that sits on the part (the head of a summary block) from the parts it stands for, and puts it on the part in place of the old one, so an outdated summary becomes valid. Slow and costs tokens of the model of the book. The part is given by its handle. Changes the book. Asynchronous.");
        setValue(L.DESC_COMMAND_REGENERATE_SUMMARY_RETURN, "JSON with the part, the tokens of the new summary and the start of its text");
        setValue(L.DESC_COMMAND_CREATE_META_SUMMARY, "Has the model merge the summaries of a range into one. Parameters: from (handle), to (handle).");
        setValue(L.DESC_COMMAND_CREATE_META_SUMMARY_LLM, "Has the model merge the summaries from the part `from` (the newest) back to the part `to` (the oldest, rounded up to the end of its summary block) into one meta summary that sits on `from` and takes the place of the summary that was there. Use it to make a long story fit into the context. Both parts are on the same branch and have summaries. Slow and costs tokens of the model of the book. Changes the book. Asynchronous.");
        setValue(L.DESC_COMMAND_CREATE_META_SUMMARY_RETURN, "JSON with the part, the tokens of the meta summary and the start of its text");
        setValue(L.DESC_COMMAND_INSERT_PART, "Inserts a new part of the story between two parts; the parts that follow stay. Parameters: text, part (handle), before (true or false).");
        setValue(L.DESC_COMMAND_INSERT_PART_LLM, "Inserts a new part with the given text into the middle of the story: right after the part `part` (its handle), or right before it when `before` is true. Everything that followed the place (all branches) follows the new part now, no part is deleted or written again, so the handles, summaries and data of the other parts stay; every part below the new one moves one position down. Use it instead of deleting and recreating the parts below. The summaries that cover the place become outdated (reported; revalidate-summaries or regenerate-summary fixes them). At the end of the branch it is the same as create-part. Changes the book. Returns the handle of the new part.");
        setValue(L.DESC_COMMAND_INSERT_PART_RETURN, "JSON with the new part (handle, position, words, tokens), how many branches continue it, the length of its branch and the summaries that became outdated");
        setValue(L.DESC_COMMAND_INSERT_ANCHOR_PARAM, "The part next to which the new one is inserted (its handle): after it, or before it when before is true");
        setValue(L.DESC_COMMAND_INSERT_BEFORE_PARAM, "true to insert before the part instead of after it; false when omitted");
        setValue(L.DESC_TEMPLATE_PREVIOUS_STORY, "The story before the part, as much of its end as fits (the older story is in the summaries).");
        setValue(L.DESC_TEMPLATE_PART_TEXT, "The text of the part being redrafted.");
        setValue(L.DESC_TEMPLATE_FOLLOWING_STORY, "The story after the part, as much as fits.");
        setValue(L.DESC_TEMPLATE_REDRAFT_INSTRUCTIONS, "What the author wants changed in the part (empty when they gave no instructions).");
        setValue(L.DESC_COMMAND_REDRAFT_PART, "Has the model write a part of the story again from instructions (any part, not only the last one), replacing its text. Costs tokens.");
        setValue(L.DESC_COMMAND_REDRAFT_PART_LLM, "Has the model write the part `part` (its handle) again and replaces its text with the result; the part may be anywhere in the story. `instructions` is what should change (\"add more dialogue\", \"make the fight longer\", \"keep the ending\"); without it the part is written again with the same events. The model sees the part, the story before it (older story as summaries) and after it, the lore the part was written with and the data of its turn. `prompt` is a redraft prompt to use instead of the one of the book (a template with the variables text, redraftInstructions, previousStory, summaries, followingStory, backgroundLore, narrativePov, narrativeTense, style, povCharacter, sceneSetting, presentCharacters, instructions); `profile` a model profile of the agent to write with instead of the model of the run; `apply` false only returns the redrafted text and leaves the part as it is (to look at it first, then replace-part-text). Replaces the text, so the summaries that cover the part become outdated (reported). Slow, costs tokens. Returns the part and, with apply false, the text.");
        setValue(L.DESC_COMMAND_REDRAFT_PART_RETURN, "JSON object: the handle, position, words, tokens and edited flag of the part, applied, the text (the whole text when apply is false) and the outdated summaries");
        setValue(L.DESC_COMMAND_REDRAFT_INSTRUCTIONS_PARAM, "What should change in the part; empty writes the part again with the same events");
        setValue(L.DESC_COMMAND_REDRAFT_PROMPT_PARAM, "A redraft prompt to use instead of the one of the book (a template); empty is the one of the book");
        setValue(L.DESC_COMMAND_REDRAFT_APPLY_PARAM, "false only returns the redrafted text and does not change the part; true (the default) replaces the text of the part");
        setValue(L.DESC_COMMAND_ANNOTATION_PARAM, "Handle of the annotation (the \"handle\" of list-annotations)");
        setValue(L.DESC_COMMAND_ANNOTATION_STATUS_FILTER_PARAM, "open (default), resolved, dismissed, orphaned or all");
        setValue(L.DESC_COMMAND_ANNOTATION_STATUS_PARAM, "resolved (default), dismissed or open");
        setValue(L.DESC_COMMAND_ANNOTATION_FILTER_PART_PARAM, "Only the annotations of this part: its handle, or its position on the active branch (the first part is 1). All parts when omitted");
        setValue(L.DESC_COMMAND_ANNOTATION_TEXT_PARAM, "The note");
        setValue(L.DESC_COMMAND_ANNOTATION_QUOTE_PARAM, "The words of the passage the note is about, copied from the part. Empty for a note about the whole part");
        setValue(L.DESC_COMMAND_ANNOTATION_TYPE_PARAM, "A free word for the kind of note (continuity, style...), empty for none");
        setValue(L.DESC_COMMAND_ANNOTATION_SEND_PARAM, "true to give the note to the model together with the part, false not to");
        setValue(L.DESC_COMMAND_LIST_ANNOTATIONS, "Lists the annotations (notes on passages) of the book or of a part. Parameters: status, part, offset, limit.");
        setValue(L.DESC_COMMAND_LIST_ANNOTATIONS_LLM, "Lists the annotations of the book, notes for the author that sit on a passage of a part (or on a whole part). Every row has its \"handle\", the handle of its part and the part's position when the part is on the active branch, the status (open, resolved, dismissed, orphaned: the passage is gone), the source (author, ai, agent, plugin), the type, the passage (start and end offsets in the text of the part and the quoted words) when it has one, and the note. The status is open when omitted, \"all\" lists every one. A part (its handle, or its position on the active branch) limits the list to it. Reads only. Options are positional and optional, in the order listed.");
        setValue(L.DESC_COMMAND_LIST_ANNOTATIONS_RETURN, "JSON with the annotations and the paging");
        setValue(L.DESC_COMMAND_GET_ANNOTATION, "Shows an annotation with its note and the passage it is about. Parameter: annotation (handle).");
        setValue(L.DESC_COMMAND_GET_ANNOTATION_LLM, "One annotation in full: the note, the status, the source, the type, the quoted passage with some text before and after it, and where it is in the part. The annotation is given by its handle (from list-annotations). Reads only.");
        setValue(L.DESC_COMMAND_GET_ANNOTATION_RETURN, "JSON with the annotation");
        setValue(L.DESC_COMMAND_CREATE_ANNOTATION, "Adds a note to a passage of a part. Parameters: part (handle), text, quote, type.");
        setValue(L.DESC_COMMAND_CREATE_ANNOTATION_LLM, "Annotates a passage of a part of the story with a note for the author. The text of the story is not changed and the note is not sent to the model. Give the words of the passage as quote, copied letter for letter (a few words are enough when they are only once in the part): the note then sits on that passage and follows it when the text is edited. Without a quote the note is about the whole part; a quote that is not in the text also makes a note about the whole part, and the answer says so. The type is a free word (continuity, style...). The part is given by its handle. Adds to the annotations of the book.");
        setValue(L.DESC_COMMAND_CREATE_ANNOTATION_RETURN, "JSON with the new annotation");
        setValue(L.DESC_COMMAND_UPDATE_ANNOTATION, "Changes the note, the type or the send to prompt flag of an annotation. Parameters: annotation (handle), text, type, sendToPrompt.");
        setValue(L.DESC_COMMAND_UPDATE_ANNOTATION_LLM, "Changes an annotation: the text of the note, its type, and whether it is given to the model together with its part (sendToPrompt). A blank text or type keeps the current one; sendToPrompt left out keeps the flag. The annotation is given by its handle (from list-annotations). The passage and the status are not changed here (see reattach-annotation and resolve-annotation).");
        setValue(L.DESC_COMMAND_UPDATE_ANNOTATION_RETURN, "JSON with the annotation");
        setValue(L.DESC_COMMAND_RESOLVE_ANNOTATION, "Sets the status of an annotation: resolved (default), dismissed or open. Parameters: annotation (handle), status.");
        setValue(L.DESC_COMMAND_RESOLVE_ANNOTATION_LLM, "Closes an annotation as resolved (the problem was dealt with) or dismissed (not worth dealing with), or opens it again (open). A closed annotation leaves the text and stays in the list. Resolved when the status is left out. The annotation is given by its handle (from list-annotations).");
        setValue(L.DESC_COMMAND_RESOLVE_ANNOTATION_RETURN, "JSON with the annotation");
        setValue(L.DESC_COMMAND_REATTACH_ANNOTATION, "Attaches an annotation to the passage that a quote finds in its part. Parameters: annotation (handle), quote.");
        setValue(L.DESC_COMMAND_REATTACH_ANNOTATION_LLM, "Moves an annotation to another passage of its part: the passage is found by the quote, which has to be copied from the text of the part. An orphaned annotation (its passage was deleted) is open again. The annotation is given by its handle (from list-annotations). Without a quote the annotation is about the whole part.");
        setValue(L.DESC_COMMAND_REATTACH_ANNOTATION_RETURN, "JSON with the annotation");
        setValue(L.DESC_COMMAND_DELETE_ANNOTATION, "Deletes an annotation. Parameter: annotation (handle).");
        setValue(L.DESC_COMMAND_DELETE_ANNOTATION_LLM, "Deletes an annotation (the user can bring it back from the trash). To close an annotation but keep it in the list use resolve-annotation. The annotation is given by its handle (from list-annotations).");
